export const provincesData = {}

Object.keys(rawData).forEach((name) => {
  const data = rawData[name]
  const spots = data.s.map(item => ({ title: item.title, imgUrl: item.imgUrl, desc: item.desc, tips: item.tips }))
  const foods = data.f.map(item => ({ name: item.name, imgUrl: item.imgUrl, desc: item.desc }))

  provincesData[name] = {
    center: allCenters[name],
    themeColor: data.c,
    banners: [spots[0].imgUrl, spots[1].imgUrl, foods[0].imgUrl, foods[1].imgUrl],
    intro: `欢迎来到${name}，这里拥有丰富的自然景观和历史文化遗产，等你来探索。`,
    spots: spots,
    foods: foods,
    guides: data.g
  }
})